BEGIN;

-- Ficha de Charytín.
--
-- La biografía de relleno la describía en términos genéricos ("irrepressible energy",
-- "true multimedia phenomenon") sin un solo hecho verificable. second_last_name: Rodríguez.
-- birth_place: se precisa a Santa Lucía, El Seibo (mayoría de fuentes sobre "El Seibo" a
-- secas; conflicto con "Santa Cruz del Seibo" de una fuente, anotado en CONFLICTOS_DE_DATO).
-- occupations: actress, comedian, television_host (no repite primary_role=singer). Dos
-- premios registrados: Premio ACE 2003 y El Soberano 2007. Luchi Vicioso no tiene ficha:
-- ver ARTISTAS_FALTANTES.md.

UPDATE artists SET second_last_name = 'Rodríguez', birth_place = 'Santa Lucía, El Seibo',
       occupations = '["actress","comedian","television_host"]'::jsonb WHERE slug = 'charytin';

INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 2003, 'Premio Extraordinario ACE por Distinción y Mérito, 35.ª entrega, Nueva York', true, 'Panamá América (21 abr 2003); nacion.com (20 abr 2003)'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'charytin' AND a.name = 'Premio ACE' AND cat.name = 'Premio ACE'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 2003);

INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 2007, 'Máxima distinción de Acroarte, por su trayectoria artística', true, 'eltiempo.com.do (27 ene 2025); El Nuevo Diario (23 may 2020); Wikipedia (es/en)'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'charytin' AND a.name = 'Premios Casandra' AND cat.name = 'El Soberano'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 2007);

