INSERT INTO editorial_entity_references (editorial_document_id, occurrence_id, entity_type, target_artist_id)
SELECT d.id, 'd0d1282d-d613-4208-84f7-eb280361a57a', 'artist', '19124a2a-a49c-435e-989e-049b5dc3726c' FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id
